contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single externally callable test that drives c and asserts the distinguishing property
    function run(address depositor, uint256 depositAmount) public {
        // need some balance in this contract to send to c
        require(address(this).balance >= depositAmount, "insufficient test funds");
        // precondition: choose a depositor that is the caller of deposit (we simulate by using msg.sender)
        // The contract C uses msg.sender for mapping; here we assume depositor == address(this) when calling
        // So we require depositor equals this contract address and then perform the call from here.
        require(depositor == address(this), "depositor must be this contract");
        // record pre-balance observed via the public getter (balances is internal in C, so we cannot read it).
        // Instead observe address(c).balance before and after plus rely on withdraw/refund behavior.

        // Ensure depositAmount > 0 to target the changed behavior
        require(depositAmount > 0, "depositAmount must be > 0");

        uint256 before = address(c).balance;
        // perform deposit into c from this contract
        c.deposit{value: depositAmount}();
        uint256 after = address(c).balance;

        // The general rule: when depositing a positive amount, the contract balance increases by exactly that amount
        // This holds in the original (which rejects zero-value overflow) but the mutant accepts zero and allows equal-case differences
        assert(after == before + depositAmount);
    }

    // allow this contract to hold ETH so it can call c.deposit{value:...}()
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        // Must have enough Ether to forward if sending value
        require(address(this).balance >= amount);
        bool reverted;
        try c.deposit{value: amount}() { reverted = false; } catch { reverted = true; }
        // General rule: if amount == 0 then original contract P requires reject (revert == true).
        // This distinguishes P (which uses assert(... > ...), rejecting zero-value) from M (which allows zero-value via require >=).
        assert((amount == 0 && reverted == true) || (amount != 0));
    }
    receive() external payable {}
}

