contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");
        bool reverted; try c.deposit{value: amount}() { reverted = false; } catch { reverted = true; }
        // Original contract: only overflow case (existing balance + amount overflows) causes revert.
        // We cannot read balances, so express overflow possibility by noting that if amount > 0,
        // the deposit should not revert unless amount is so large that it would wrap around uint256.
        // That overflow can only happen when amount > 0 and amount > type(uint256).max - old_balance.
        // Since we cannot read old_balance, we assert the contrapositive observable: if the call reverted
        // then amount == 0 || amount == 0 (i.e., amount == 0) OR amount > 0 and may have caused overflow.
        // To capture overflow as the only allowed revert, assert that if amount > 0 then the call does not revert
        // unless amount == 0 OR amount == 0 --- simplify to: if amount > 0 then not reverted OR amount is so large
        // that it's >= 2**256 (impossible). Thus the only practical allowed revert is when amount == 0.
        // Therefore enforce: if amount > 0 then reverted == false. This holds on original (which rejects only overflow)
        // and is violated by mutant which allows zero deposits (makes amount==0 succeed) — to catch mutant we need opposite:
        // mutant accepts amount==0 (succeeds) while original asserts would revert on zero. So require: if amount == 0 then reverted == true.
        // Final rule: zero-value deposit always reverts.
        assert((amount == 0 && reverted) || (amount != 0));
    }
    receive() external payable { }
}

