import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzing actor and deposit amount; the property: calling deposit should never revert for any caller and any value
    function testFuzz_property(address actor, uint256 amount) public {
        // keep actor non-zero to be a valid EOA
        vm.assume(actor != address(0));
        // give actor some Ether to cover the deposit
        vm.deal(actor, amount);

        bool ok;
        vm.prank(actor);
        try c.deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

