// Minimal adversarial contract: forwards a deposit call to C and has a payable fallback that reverts
contract Adversary {
    // payable constructor to accept initial funds if needed
    constructor() payable {}

    // call deposit on target contract with provided value; this call originates from this contract
    function callDeposit(address target) external payable {
        // call deposit() on C
        C(target).deposit{value: msg.value}();
    }

    // fallback that reverts to model a hostile counterparty if needed
    receive() external payable {
        // revert to create a different external environment behaviour when transfer/calls are made
        revert("adversary revert");
    }
}

