pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz the depositor address and amount. The adversarial helper is a reentrant contract
    // that on its receive() will call deposit() again to try to manipulate balances and trigger
    // the mutant's require to revert in some interleaving. The reference uses assert(...) and
    // will not revert for any admissible input, so deposit should always succeed on reference.
    function testFuzz_property(address depositor, uint256 amount) public {
        // bound amount to a reasonable range so vm.deal works and keeps domain wide
        amount = bound(amount, 0, 1 ether);
        // depositor must be non-zero
        vm.assume(depositor != address(0));

        // Deploy adversarial helper that will reenter once when receiving ETH
        ReentrantHelper helper = new ReentrantHelper(address(c));

        // Fund depositor and helper so they can send ETH
        vm.deal(depositor, amount);
        // also fund helper so it can forward ETH if needed
        vm.deal(address(helper), 0);

        bool ok;
        // Try calling deposit from the helper via a prank of depositor: send to helper first so it can reenter
        // We choose to call c.deposit via the helper by sending ETH to helper and having helper forward
        // It is important we fuzz depositor (the externally-owned-sender) and amount; helper is the adversary

        // If depositor sends ETH to helper which then forwards to c and reenters, the mutant may revert
        vm.prank(depositor);
        try helper.doSend{value: amount}(depositor, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: on the correct reference C, deposit never reverts for any admissible input,
        // therefore the call above must succeed (ok == true) for all fuzz inputs when running the reference.
        // The mutant, however, is known to fail for some inputs (the fuzzer will find those when run against the mutant).
        assertTrue(ok);
    }
}

// Minimal adversarial helper that on receiving ETH will forward it to C and perform a reentrant deposit call once.
contract ReentrantHelper {
    C immutable c;
    bool reentered;

    constructor(address _c) {
        c = C(_c);
        reentered = false;
    }

    // Called by depositor in the test: this function sends ETH to c.deposit() from this contract,
    // causing its receive() to be invoked if c were to send back (not the case), but the helper
    // itself performs a reentrant deposit during forwarding to try to create an interleaving.
    function doSend(address /* depositor */, uint256 amount) external payable {
        // Forward the received ETH to c.deposit(), but do a reentrant call before finishing to simulate attack
        // First call deposit once (this is the primary deposit)
        c.deposit{value: msg.value}();
        // Then, if not yet reentered, attempt a reentrant deposit (this will be from this contract again)
        if (!reentered) {
            reentered = true;
            // perform a second deposit with zero value to attempt to trigger edge cases
            c.deposit{value: 0}();
        }
    }

    // allow receiving ETH
    receive() external payable {}
}

