pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz params: actor (the caller) and amount to deposit
    function testFuzz_property(address actor, uint256 amount) public {
        // keep actor non-zero and amount bounded to a reasonable range
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1 ether);

        // fund the actor so they can send value
        vm.deal(actor, amount);

        // Make a malicious helper that will re-enter into c.deposit() during transfer if needed.
        // Deploy it from the actor so it becomes the sender for deposits we originate via the helper.
        vm.startPrank(actor);
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.stopPrank();

        // Send the deposit from the attacker contract to c; attacker will try to re-enter on receiving funds.
        // We capture whether the call succeeded or reverted for the deposit call.
        bool ok;
        vm.prank(actor);
        // transfer ETH to attacker so it can call deposit
        payable(address(attacker)).transfer(amount);

        try attacker.depositToC{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract C never reverts on deposit for any caller/amount; thus ok must be true.
        // The buggy mutant can revert for some inputs (attacker & amount) due to the changed check.
        assertTrue(ok);
    }
}

// Minimal reentrant helper: on receiving ETH it does nothing special, but it has a function
// depositToC() that calls c.deposit() and during fallback can re-enter if desired.
contract ReentrantAttacker {
    C public target;
    bool public reentered;

    constructor(C _target) payable {
        target = _target;
    }

    // receive will try a reentrant deposit once when receiving funds by first forwarding to target.deposit()
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // Attempt a reentrant deposit of 0 value
            // This models an adversarial caller that could influence balances before the outer deposit completes
            // The call is allowed to fail; test observes the outer deposit call's success via try/catch above.
            try target.deposit{value: 0}() {
            } catch {
            }
        }
    }

    // Called by the externally-owned actor to initiate a deposit into the target using this contract as sender
    function depositToC() external payable {
        // forward the entire value to target.deposit()
        target.deposit{value: msg.value}();
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // drive: perform one deposit from this contract and then observe recorded balances and contract balance
    function check_invariant(uint256 value) public payable {
        // require this test contract has enough ETH to send
        require(address(this).balance >= value, "insufficient test funds");
        // read balance before
        uint256 before = c.balances(address(this));
        // perform deposit sending value
        c.deposit{value: value}();
        // read balance after
        uint256 after = c.balances(address(this));
        // The intended invariant in original: for positive value, after == before + value
        // This is violated by mutant that removed the overflow/assert guard (it allows value==0 or overflow),
        // but specifically removing the assert permits silent overflow making after <= before for crafted value.
        assert(value == 0 ? after == before : after == before + value);
    }

    // allow contract to receive ETH so tests can fund it
    receive() external payable {}
}

