contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // take amount to send to deposit
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        // call deposit with `amount` wei
        bool reverted; try c.deposit{value: amount}() { reverted = false; } catch { reverted = true; }
        // The original contract ensures that if the addition would not overflow, deposit never reverts.
        // Expressed without accessing private balances: if amount is such that existing balance + amount <= type(uint256).max,
        // then deposit should not revert. We cannot read existing balance, but we can ensure the test caller
        // hasn't previously deposited more than uint256.max - amount by requiring amount itself <= type(uint256).max.
        // Instead, we assert that when amount is strictly less than 2**255 (an arbitrary non-overflow-safe bound)
        // this still must hold for original contract. To precisely capture overflow condition without reading balances,
        // we instead require amount == 0 || reverted == false when amount <= type(uint256).max; equivalently,
        // assert that if reverted is true then amount > 0 and amount > 0 triggers potential overflow in mutant.
        // More directly: For all amounts, if the caller sends amount such that amount == amount (always true),
        // original never reverts due to overflow guard, so reverted must be false for any amount that does not by itself overflow.
        // Therefore we assert that if amount <= type(uint256).max then reverted == false.
        // (This captures that M can revert due to overflow but P cannot.)
        assert(amount <= type(uint256).max ? reverted == false : true);
    }
    receive() external payable {}
}
